package main

// Learn cards for web languages: HTML, Markdown, JavaScript, TypeScript and
// data files (JSON, YAML, TOML). Same layout as the CSS card in learn_css.go.

var learnHTML = learnTopic{
	Name:   "HTML",
	Match:  []string{"html", "xhtml", "vue", "svelte", ".html", ".htm", ".xhtml", ".vue", ".svelte", ".astro"},
	Source: "WHATWG HTML (semantics, sections, grouping, forms, input, interactive elements, popover, interaction, obsolete) · MDN (aria-live, img, dialog, popover, fetchpriority)",
	Sections: []learnSection{
		{Title: "Page skeleton", Keys: []string{"head", "meta", "link"}, Items: []learnItem{
			{Use: "<!doctype html>", Keys: []string{"doctype"}, Why: "The first line of every page. It puts the browser in standards mode.",
				Like: "Like the title page of a form that says which version of the form it is.", Example: "<!doctype html>\n<html lang=\"en\">"},
			{Use: "<html lang=\"en\">", Keys: []string{"lang"}, Why: "Sets the language of the page. Screen readers and translation tools use it.",
				Like: "Like a label on a parcel that says which language the letter inside is written in.", Example: "<html lang=\"en\">"},
			{Use: "<meta charset=\"utf-8\">", Keys: []string{"charset", "utf-8"}, Why: "Must be in the first 1024 bytes of the file. Put it first in <head>.",
				Like: "Like telling a reader which alphabet a book uses before they open it.", Example: "<head>\n  <meta charset=\"utf-8\">"},
			{Use: "<meta name=\"viewport\">", Keys: []string{"viewport", "width=device-width"}, Why: "content=\"width=device-width, initial-scale=1\". Without it, phones show a shrunken desktop page.",
				Like: "Like telling a tailor the real size of the person, so the clothes fit.", Example: "<meta name=\"viewport\"\n  content=\"width=device-width, initial-scale=1\">"},
			{Use: "<title>", Why: "Every page needs a title. Browsers show it in tabs and bookmarks.",
				Like: "Like the name on the spine of a book on a shelf.", Example: "<title>Contact us | My Shop</title>"},
			{Use: "<script type=\"module\">", Keys: []string{"script", "module"}, Why: "Modern scripts. Module scripts are deferred by default: they run after the page is parsed.",
				Like: "Like a builder who waits until the walls are up before putting in the lights.", Example: "<script type=\"module\" src=\"/js/app.js\"></script>"},
			{Use: "<script defer>", Keys: []string{"defer"}, Why: "Classic scripts. The file downloads during parsing and runs after the page is parsed.",
				Like: "Like ordering parts early and fitting them when the frame is finished.", Example: "<script defer src=\"/js/analytics.js\"></script>"},
		}},
		{Title: "Semantic structure", Items: []learnItem{
			{Use: "<header> · <footer>", Why: "The introduction and the closing part of the page, or of an article.",
				Like: "Like the letterhead and the signature block of a letter.", Example: "<header><h1>My Blog</h1></header>\n<footer><p>© 2026 My Blog</p></footer>"},
			{Use: "<nav>", Why: "A section of main navigation links.",
				Like: "Like the signposts in a building that point to each floor.", Example: "<nav>\n  <a href=\"/\">Home</a> <a href=\"/about\">About</a>\n</nav>"},
			{Use: "<main>", Why: "The main content of the page. Only one <main> without the hidden attribute is allowed.",
				Like: "Like the main room of a house, not the hallway or the cupboards.", Example: "<main id=\"content\">\n  <h1>Welcome</h1>\n</main>"},
			{Use: "<article>", Why: "Content that makes sense on its own: a blog post, a comment, a product card.",
				Like: "Like a single newspaper article that could be cut out and still make sense.", Example: "<article>\n  <h2>Post title</h2>\n</article>"},
			{Use: "<section>", Why: "A themed part of the page. It usually has a heading. For a plain styling box, use <div>.",
				Like: "Like a chapter in a book, with its own chapter title.", Example: "<section>\n  <h2>Features</h2>\n</section>"},
			{Use: "<aside>", Why: "Content related to the main text but separate from it: notes, related links.",
				Like: "Like a box in the margin of a textbook with an extra fact.", Example: "<aside>\n  <h2>Related posts</h2>\n</aside>"},
			{Use: "<h1> … <h6>", Keys: []string{"h1", "h2", "h3", "h4", "h5", "h6"}, Why: "Headings by structure, not by size. Go down one level at a time: h1, then h2, not h3. Screen reader users move by headings.",
				Like: "Like the numbered headings in a report: 1, then 1.1, then 1.1.1.", Example: "<h1>Settings</h1>\n<h2>Account</h2>\n<h3>Password</h3>"},
			{Use: "<figure> · <figcaption>", Why: "An image, chart or code sample together with its caption.",
				Like: "Like a photo in a museum with its small card underneath.", Example: "<figure>\n  <img src=\"chart.png\" alt=\"Sales rose 20% in May\">\n  <figcaption>Monthly sales, 2026</figcaption>"},
		}},
		{Title: "Images and media", Keys: []string{"img", "image", "src"}, Items: []learnItem{
			{Use: "alt=\"…\"", Keys: []string{"alt"}, Why: "Every <img> needs alt. Describe what the image shows or does.",
				Like: "Like describing a photo to a friend on the phone.", Example: "<img src=\"team.jpg\" alt=\"Our team at the 2026 meetup\">"},
			{Use: "alt=\"\"", Why: "An empty alt marks a decorative image. Screen readers skip it.",
				Like: "Like a tour guide who walks past the wallpaper without describing it.", Example: "<img src=\"divider.svg\" alt=\"\">"},
			{Use: "width · height", Why: "Set both on <img>. The browser keeps the space before the image loads, so the page does not jump.",
				Like: "Like saving a seat with a coat before the person arrives.", Example: "<img src=\"hero.jpg\" alt=\"Lake at sunrise\"\n  width=\"1200\" height=\"600\">"},
			{Use: "loading=\"lazy\"", Keys: []string{"lazy"}, Why: "For images and iframes below the first screen. Do not use it on the main image at the top.",
				Like: "Like a waiter who brings each course when you are ready for it, not all at once.", Example: "<img src=\"map.png\" alt=\"Office map\" loading=\"lazy\">"},
			{Use: "fetchpriority=\"high\"", Why: "On the main image at the top, so it loads first. Baseline 2024; older browsers ignore it.",
				Like: "Like a priority boarding pass for the most important passenger.", Example: "<img src=\"hero.jpg\" alt=\"Lake at sunrise\"\n  fetchpriority=\"high\">"},
			{Use: "srcset · sizes", Why: "Lists several sizes of one image. The browser picks the right one for the screen.",
				Like: "Like a shoe shop that has the same shoe in many sizes.", Example: "<img src=\"cat-800.jpg\" alt=\"A cat on a sofa\"\n  srcset=\"cat-400.jpg 400w, cat-800.jpg 800w\"\n  sizes=\"(max-width: 600px) 100vw, 50vw\">"},
			{Use: "<picture> · <source>", Why: "Offers newer formats (AVIF, WebP) first, with a JPEG or PNG <img> as the fallback.",
				Like: "Like a menu that offers a new dish and keeps the classic one for those who want it.", Example: "<picture><source srcset=\"hero.avif\" type=\"image/avif\">\n  <img src=\"hero.jpg\" alt=\"Lake at sunrise\">\n</picture>"},
			{Use: "autoplay muted", Keys: []string{"autoplay", "video"}, Why: "Browsers block autoplay with sound. Add muted if a video must start by itself.",
				Like: "Like a shop display that plays silently, so it does not startle people walking past.", Example: "<video src=\"intro.mp4\" autoplay muted loop\n  playsinline></video>"},
		}},
		{Title: "Buttons, links and forms", Keys: []string{"form", "input", "select", "textarea", "option"}, Items: []learnItem{
			{Use: "<button type=\"button\">", Keys: []string{"button"}, Why: "Anything that does an action. Keyboard use and screen reader support are built in.",
				Like: "Like a light switch: you press it and something happens here.", Example: "<button type=\"button\">Show more</button>"},
			{Use: "<a href=\"…\">", Keys: []string{"href"}, Why: "Anything that goes to another page or another place on the page.",
				Like: "Like a door: you go through it to somewhere else.", Example: "<a href=\"/pricing\">See pricing</a>"},
			{Use: "<label for=\"id\">", Keys: []string{"label", "for"}, Why: "Every input needs a label. Clicking the label focuses the input, or ticks a checkbox.",
				Like: "Like the printed name next to each box on a paper form.", Example: "<label for=\"email\">Email</label>\n<input id=\"email\" name=\"email\" type=\"email\">"},
			{Use: "type=\"email\" · \"tel\" · \"url\"", Keys: []string{"type"}, Why: "Phones show the right keyboard. The browser checks the format of email and url. tel has no format check.",
				Like: "Like a form box that says 'date of birth', so you know to write a date.", Example: "<input type=\"email\" name=\"email\">\n<input type=\"tel\" name=\"phone\">\n<input type=\"url\" name=\"website\">"},
			{Use: "inputmode=\"numeric\"", Keys: []string{"inputmode"}, Why: "Shows a number keypad. Use it with type=\"text\" for codes and card numbers.",
				Like: "Like handing someone a calculator when they only need to type digits.", Example: "<input type=\"text\" name=\"code\" inputmode=\"numeric\"\n  autocomplete=\"one-time-code\">"},
			{Use: "autocomplete=\"email\"", Keys: []string{"autocomplete"}, Why: "Tells browsers and password managers what to fill in this field.",
				Like: "Like a clerk who already knows your address and fills it in for you.", Example: "<input type=\"email\" name=\"email\" autocomplete=\"email\">"},
			{Use: "required · minlength · pattern", Why: "The browser checks the field before the form is sent. Always check again on the server.",
				Like: "Like a post office clerk who checks the address before the parcel goes out.", Example: "<input name=\"user\" required minlength=\"3\"\n  pattern=\"[a-z0-9]+\">"},
			{Use: "<fieldset> · <legend>", Why: "Groups related controls, such as a set of radio buttons, under one name.",
				Like: "Like a boxed area on a paper form titled 'Delivery address'.", Example: "<fieldset><legend>Size</legend>\n  <label><input type=\"radio\" name=\"size\"> Small</label>\n</fieldset>"},
		}},
		{Title: "Built-in interactive parts", Items: []learnItem{
			{Use: "<dialog>", Keys: []string{"showmodal"}, Why: "A dialog box. showModal() makes the rest of the page inert. The Esc key closes it.",
				Like: "Like a clerk who asks you one question and waits for the answer before going on.", Example: "<dialog id=\"dlg\">Delete this file?</dialog>\n<script>document.querySelector(\"#dlg\").showModal()</script>"},
			{Use: "<form method=\"dialog\">", Why: "Inside a <dialog>: submitting this form closes the dialog.",
				Like: "Like an 'OK' slip that ends the conversation when you hand it back.", Example: "<dialog>\n  <form method=\"dialog\"><button>Close</button></form>\n</dialog>"},
			{Use: "popover", Why: "An element that shows on top of the page. With the default value (auto), a click outside or Esc closes it. Baseline 2024.",
				Like: "Like a sticky note you put on top of a page and peel off again.", Example: "<div id=\"tip\" popover>Saved to your account.</div>"},
			{Use: "popovertarget=\"id\"", Why: "On a <button>: shows and hides the popover with that id. No script needed.",
				Like: "Like a light switch wired to one lamp.", Example: "<button popovertarget=\"menu\">Menu</button>\n<ul id=\"menu\" popover><li>Profile</li></ul>"},
			{Use: "<details> · <summary>", Why: "A section that opens and closes on click. No script needed.",
				Like: "Like a folded note: the outside says what is inside, and you unfold it to read.", Example: "<details><summary>Shipping costs</summary>\n  <p>Free over 50 euros.</p>\n</details>"},
			{Use: "inert", Why: "Makes part of the page unclickable and unfocusable, for example behind an open panel.",
				Like: "Like a rope across a closed part of a museum.", Example: "<main inert>…</main>\n<aside class=\"panel\">Filters</aside>"},
		}},
		{Title: "Accessibility", Keys: []string{"aria", "role"}, Items: []learnItem{
			{Use: "native elements first", Why: "A real <button> needs no ARIA. Use ARIA only when HTML has no element for the job.",
				Like: "Like using a real door instead of painting a door on the wall and adding a sign.", Example: "<button type=\"button\">Save</button>"},
			{Use: "aria-label=\"…\"", Why: "Gives a name to a control that has no visible text, such as an icon-only button.",
				Like: "Like a name tag on a person who is not wearing a uniform.", Example: "<button type=\"button\" aria-label=\"Close\">×</button>"},
			{Use: "aria-expanded", Why: "On a button that shows or hides something. The value is \"true\" or \"false\".",
				Like: "Like a sign on a drawer that says 'open' or 'closed'.", Example: "<button aria-expanded=\"false\" aria-controls=\"nav\">\n  Menu\n</button>"},
			{Use: "aria-live=\"polite\"", Why: "Screen readers announce changes inside this area at the next pause, such as the end of the current sentence. They do not interrupt.",
				Like: "Like an assistant who waits for a pause before telling you news.", Example: "<p id=\"status\" aria-live=\"polite\">3 results found</p>"},
			{Use: "tabindex=\"0\" · \"-1\"", Keys: []string{"tabindex"}, Why: "0 adds a custom control to the Tab order. -1 keeps it out of the Tab order; scripts and clicks can still focus it.",
				Like: "Like adding a new stop to a bus route, or a stop used only on request.", Example: "<div class=\"table-wrap\" tabindex=\"0\">…</div>\n<h1 id=\"title\" tabindex=\"-1\">Results</h1>"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "<div onclick>", Keys: []string{"onclick", "div"}, Why: "A <div> cannot be reached with the keyboard and is not announced as a button. Use <button>.",
				Like: "Like a door handle painted on a wall: it looks right but does not open.", Example: "<!-- instead: -->\n<button type=\"button\" id=\"save\">Save</button>"},
			{Use: "<a href=\"#\"> as a button", Why: "Links go somewhere. Use <button> for actions.",
				Like: "Like a door that leads to the same room you are standing in.", Example: "<!-- instead: -->\n<button type=\"button\" id=\"more\">Show more</button>"},
			{Use: "<table> for layout", Why: "Tables are for data in rows and columns. Use CSS grid or flex for layout.",
				Like: "Like building a house out of spreadsheet printouts.", Example: "<!-- instead: -->\n<div class=\"grid\"><nav>…</nav><main>…</main></div>"},
			{Use: "<br><br> for spacing", Keys: []string{"br"}, Why: "Use CSS margin or gap for space. <br> is for line breaks inside text, such as an address.",
				Like: "Like pressing Enter many times in a letter instead of setting the margins.", Example: "<!-- instead: -->\n<p>First paragraph.</p>\n<p>Second paragraph.</p>"},
			{Use: "tabindex=\"1\" or higher", Why: "Positive values change the Tab order away from the reading order. Use 0 or -1.",
				Like: "Like numbering seats in a theatre out of order.", Example: "<!-- instead: -->\n<div class=\"card\" tabindex=\"0\">…</div>"},
			{Use: "<center> · <font>", Keys: []string{"center", "font"}, Why: "Obsolete in HTML. Use CSS.",
				Like: "Like using a typewriter's settings in a word processor.", Example: "<!-- instead: -->\n<style>.note { text-align: center; color: gray; }</style>\n<p class=\"note\">Hello</p>"},
			{Use: "style=\"…\" everywhere", Keys: []string{"style"}, Why: "Inline styles are hard to reuse and to override. Put styles in CSS classes.",
				Like: "Like writing paint colours on every single brick instead of on the plan.", Example: "<!-- instead: -->\n<link rel=\"stylesheet\" href=\"/css/site.css\">\n<p class=\"warning\">Check your email.</p>"},
		}},
	},
}

var learnMarkdown = learnTopic{
	Name:   "Markdown",
	Match:  []string{"markdown", ".md", ".markdown", ".mdx"},
	Source: "CommonMark 0.31.2 spec · GitHub Flavored Markdown spec (tables, task lists, hard breaks)",
	Sections: []learnSection{
		{Title: "Headings", Items: []learnItem{
			{Use: "# Title", Keys: []string{"#"}, Why: "An ATX heading: 1 to 6 # signs, then a space or a tab, then the text.",
				Like: "Like the big title on the front of a report.", Example: "# Getting started"},
			{Use: "## Section", Keys: []string{"##", "###"}, Why: "Each extra # is one level lower. Go down one level at a time.",
				Like: "Like the numbered headings in a report: 1, then 1.1, then 1.1.1.", Example: "## Installation\n### On Linux"},
			{Use: "empty line around blocks", Why: "Put an empty line before and after headings, lists, tables and code blocks. The spec does not always require it, but it prevents surprises.",
				Like: "Like the space between paragraphs in a printed book.", Example: "Some text.\n\n## Usage"},
		}},
		{Title: "Text", Items: []learnItem{
			{Use: "**bold**", Keys: []string{"**"}, Why: "Strong emphasis. ** also works inside a word; __ does not.",
				Like: "Like saying a word louder.", Example: "**Note:** back up your files first."},
			{Use: "*italic*", Keys: []string{"*", "_"}, Why: "Emphasis. * also works inside a word; _ does not.",
				Like: "Like leaning on a word when you speak.", Example: "This is *not* the same file."},
			{Use: "`code`", Keys: []string{"`"}, Why: "Inline code: commands, file names, values. Backslash escapes do not work inside it. A line break inside it becomes a space.",
				Like: "Like quoting a sign word for word.", Example: "Run `npm install` in the project folder."},
			{Use: "empty line", Why: "An empty line starts a new paragraph. A single line break is a soft break: browsers show it as a space.",
				Like: "Like a new paragraph in a letter.", Example: "First paragraph.\n\nSecond paragraph."},
			{Use: "\\ at line end", Keys: []string{"\\"}, Why: "A backslash at the end of a line makes a hard line break inside a paragraph.",
				Like: "Like the line breaks in a postal address.", Example: "Jane Doe\\\n12 High Street"},
			{Use: "\\*", Why: "A backslash before an ASCII punctuation character shows that character as plain text.",
				Like: "Like putting a word in quotes to say 'I mean this word itself'.", Example: "Fields marked \\* are required."},
		}},
		{Title: "Lists", Items: []learnItem{
			{Use: "- item", Keys: []string{"-"}, Why: "A bullet list item. Use one symbol for the whole list.",
				Like: "Like a shopping list.", Example: "- Milk\n- Bread\n- Eggs"},
			{Use: "1. item", Why: "A numbered list item. The first number sets the start. The renderer numbers the rest.",
				Like: "Like the steps of a recipe.", Example: "1. Clone the repo\n2. Run make\n3. Open the app"},
			{Use: "  - nested", Why: "Indent to where the parent's text starts: 2 spaces after -, 3 spaces after 1.",
				Like: "Like sub-points written under a point, lined up with its words.", Example: "- Fruit\n  - Apples\n  - Pears"},
			{Use: "- [ ] task · - [x] done", Keys: []string{"[ ]", "[x]"}, Why: "A task list item, from GitHub Flavored Markdown.",
				Like: "Like a to-do list with tick boxes.", Example: "- [x] Write tests\n- [ ] Update the docs"},
		}},
		{Title: "Code blocks", Keys: []string{"```", "~~~"}, Items: []learnItem{
			{Use: "```js", Why: "A fenced code block. The word after the fence names the language, for syntax colours.",
				Like: "Like a framed sign that says which language the text inside is in.", Example: "```js\nconst x = 1;\n```"},
			{Use: "```", Why: "Closes the block. The closing fence needs at least as many backticks as the opening one.",
				Like: "Like closing a bracket you opened.", Example: "```sh\nnpm test\n```"},
			{Use: "````", Why: "Use a longer fence when the code itself contains ```.",
				Like: "Like a bigger box around a box.", Example: "````md\n```js\n````"},
			{Use: "~~~", Why: "Tildes also make a fence. The same rules apply as for backticks.",
				Like: "Like a second kind of bracket you can use.", Example: "~~~python\nprint(\"hi\")\n~~~"},
		}},
		{Title: "Links and images", Keys: []string{"link", "url"}, Items: []learnItem{
			{Use: "[text](https://…)", Why: "An inline link. The text should say where the link goes.",
				Like: "Like a sign that says 'Train station' instead of 'This way'.", Example: "[Read the install guide](https://example.com/install)"},
			{Use: "[text][ref]", Why: "A reference link. It keeps long URLs out of the sentence.",
				Like: "Like a footnote number that points to the full address at the bottom.", Example: "See the [install guide][install] first."},
			{Use: "[ref]: https://…", Why: "Defines a reference. It can be anywhere in the file; the end is common.",
				Like: "Like the list of addresses at the back of a guidebook.", Example: "[install]: https://example.com/docs/install"},
			{Use: "<https://…>", Why: "An autolink: the URL itself becomes a link.",
				Like: "Like a web address printed on a poster.", Example: "Questions? <https://example.com/help>"},
			{Use: "![alt text](image.png)", Keys: []string{"!["}, Why: "An image. The text in [ ] becomes the alt text. Describe the image.",
				Like: "Like the caption that tells a listener what a photo shows.", Example: "![Screenshot of the settings page](img/settings.png)"},
		}},
		{Title: "Tables (GFM)", Keys: []string{"|", "table"}, Items: []learnItem{
			{Use: "| Name | Size |", Why: "The header row. Pipes at the start and end are optional but clearer.",
				Like: "Like the column titles at the top of a timetable.", Example: "| Name | Size |\n| ---- | ---- |\n| app.js | 4 KB |"},
			{Use: "| --- | --- |", Why: "The delimiter row. It is required directly under the header row.",
				Like: "Like the line drawn under the column titles.", Example: "| File | Lines |\n| --- | --- |\n| main.go | 120 |"},
			{Use: "| :-- | :-: | --: |", Keys: []string{":--", ":-:", "--:"}, Why: "Colons set the alignment: left, centre or right.",
				Like: "Like setting a column in a spreadsheet to align left, centre or right.", Example: "| Item | Qty | Price |\n| :--- | :-: | ----: |\n| Tea  |  2  |  3.50 |"},
			{Use: "\\|", Why: "A pipe character inside a cell needs a backslash before it.",
				Like: "Like writing a comma inside quotes so it is not read as a separator.", Example: "| Operator | Meaning |\n| --- | --- |\n| `a \\| b` | a or b |"},
		}},
		{Title: "Other blocks", Items: []learnItem{
			{Use: "> quote", Keys: []string{">"}, Why: "A block quote. Start each line with >.",
				Like: "Like an indented quotation in a book.", Example: "> **Note:** this API is still in beta."},
			{Use: "---", Why: "A thematic break (a line). Put an empty line above it, or the text above becomes a heading.",
				Like: "Like the small line between scenes in a novel.", Example: "End of part one.\n\n---"},
			{Use: "<!-- note -->", Keys: []string{"<!--"}, Why: "An HTML comment. It is not shown in the output.",
				Like: "Like a pencil note in the margin that does not get printed.", Example: "<!-- TODO: add screenshots -->"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "=== or --- underlines", Keys: []string{"==="}, Why: "Setext headings only make levels 1 and 2. # headings make all 6 levels.",
				Like: "Like a ruler that only measures up to 2 cm.", Example: "<!-- instead: -->\n# Title\n## Subtitle"},
			{Use: "#Heading (no space)", Why: "Without a space after #, it is plain text, not a heading.",
				Like: "Like a title written without a gap: the reader does not see it as a title.", Example: "<!-- instead: -->\n# Heading"},
			{Use: "mixing - * + bullets", Keys: []string{"+"}, Why: "Changing the bullet symbol starts a new list.",
				Like: "Like switching to a new sheet of paper halfway through a list.", Example: "<!-- instead: -->\n- Apples\n- Pears"},
			{Use: "4-space indented code", Why: "An indented code block cannot name a language. Use ``` fences.",
				Like: "Like a parcel with no label on it.", Example: "<!-- instead: -->\n```sh\nmake test\n```"},
			{Use: "two trailing spaces", Why: "This line break is invisible. Many editors delete trailing spaces. Use \\ instead.",
				Like: "Like a message written in invisible ink.", Example: "<!-- instead: -->\nJane Doe\\\n12 High Street"},
			{Use: "raw HTML for layout", Why: "GitHub and many other sites remove some HTML tags and attributes. Use plain Markdown.",
				Like: "Like sending furniture through a door that is too narrow for it.", Example: "<!-- instead: -->\n## Features\n- Fast startup"},
		}},
	},
}

var learnJavaScript = learnTopic{
	Name:   "JavaScript",
	Match:  []string{"javascript", "react", "jsx", ".js", ".mjs", ".cjs", ".jsx"},
	Source: "MDN (Promise.all, toSorted, Error.stack, structuredClone) · Node.js docs (ESM, globals fetch) · ECMA-262 via MDN",
	Sections: []learnSection{
		{Title: "Variables", Items: []learnItem{
			{Use: "const", Why: "The default for every variable. The name cannot be given a new value. Objects inside can still change.",
				Like: "Like a name tag glued to one box. You can change what is in the box, not which box it is.", Example: "const MAX_RETRIES = 3;\nconst user = { name: \"Ana\" };\nuser.name = \"Bo\";"},
			{Use: "let", Why: "Only when the variable must get a new value, such as a counter. It is block-scoped.",
				Like: "Like a whiteboard: you wipe it and write a new number.", Example: "let total = 0;\nfor (const item of cart) total += item.price;"},
			{Use: "const { a, b } = obj", Keys: []string{"destructuring"}, Why: "Destructuring: takes fields out of an object into variables in one line.",
				Like: "Like unpacking a bag and putting each item on its own shelf.", Example: "const { id, name } = user;\nconst { x = 0, y = 0 } = point;"},
			{Use: "const [first, ...rest] = list", Why: "Array destructuring. ... collects the remaining items into a new array.",
				Like: "Like taking the top card and keeping the rest of the deck together.", Example: "const [first, ...rest] = names;\nconst [key, value] = entry;"},
			{Use: "{ ...obj, a: 1 }", Keys: []string{"...", "spread"}, Why: "A shallow copy with changes. The original object stays the same.",
				Like: "Like photocopying a form and correcting one box on the copy.", Example: "const next = { ...user, name: \"Ana\" };\nconst all = [...oldItems, newItem];"},
			{Use: "`Hi ${name}`", Keys: []string{"${", "`"}, Why: "A template literal: joins text and values. It can span several lines.",
				Like: "Like a form letter with blanks that get filled in.", Example: "const url = `/api/users/${id}`;\nconsole.log(`Saved ${count} files`);"},
		}},
		{Title: "Comparing and missing values", Items: []learnItem{
			{Use: "=== · !==", Why: "Compares without converting types. \"1\" == 1 is true; \"1\" === 1 is false.",
				Like: "Like checking both the name and the photo on an ID card.", Example: "if (status === \"done\") showToast();\nif (items.length !== 0) render(items);"},
			{Use: "a?.b · a?.[i] · f?.()", Keys: []string{"?."}, Why: "Optional chaining. If a is null or undefined, the result is undefined instead of an error.",
				Like: "Like knocking on a door only if the house is there.", Example: "const city = user?.address?.city;\nconst first = list?.[0];\nonDone?.();"},
			{Use: "a ?? b", Keys: []string{"??"}, Why: "Gives b only when a is null or undefined. 0, \"\" and false are kept.",
				Like: "Like a substitute teacher who only comes when the teacher is absent, not when the teacher is quiet.", Example: "const limit = options.limit ?? 20;"},
			{Use: "a ??= b", Keys: []string{"??="}, Why: "Sets a to b only when a is null or undefined.",
				Like: "Like filling in a blank box on a form and leaving filled boxes alone.", Example: "options.retries ??= 3;\ncache[key] ??= compute(key);"},
			{Use: "Number.isNaN(x)", Keys: []string{"nan", "isnan"}, Why: "Checks for NaN without converting x. x === NaN is always false.",
				Like: "Like checking the label on a jar instead of guessing from the colour.", Example: "const n = Number(input.value);\nif (Number.isNaN(n)) showError(\"Not a number\");"},
		}},
		{Title: "Functions", Keys: []string{"function", "return"}, Items: []learnItem{
			{Use: "(a, b) => a + b", Keys: []string{"=>"}, Why: "An arrow function. It uses the this of the code around it. Good for callbacks.",
				Like: "Like a helper who works in your office and uses your desk.", Example: "const names = users.map((u) => u.name);\nbutton.addEventListener(\"click\", () => save());"},
			{Use: "function name() {}", Why: "A function declaration. It is hoisted: you can call it above the line where it is written.",
				Like: "Like a name in the table of contents: you can find it before you reach its page.", Example: "function formatPrice(cents) {\n  return `$${(cents / 100).toFixed(2)}`;\n}"},
			{Use: "function f(x = 1)", Why: "A default value, used when the argument is missing or undefined.",
				Like: "Like a coffee order that is 'medium' unless you say otherwise.", Example: "function greet(name = \"friend\") {\n  return `Hello, ${name}!`;\n}"},
			{Use: "function f({ id, name })", Why: "One options object instead of many arguments in a fixed order. Each value has a name.",
				Like: "Like a labelled form instead of a list of answers you must keep in order.", Example: "function createUser({ name, email, role = \"user\" }) {\n  return { name, email, role };\n}"},
			{Use: "(...args) =>", Keys: []string{"arguments"}, Why: "Rest parameters: all remaining arguments as a real array. Use them instead of arguments.",
				Like: "Like a basket that collects everyone who arrives after the first guests.", Example: "function sum(...nums) {\n  return nums.reduce((a, b) => a + b, 0);\n}"},
		}},
		{Title: "Arrays, objects and loops", Keys: []string{"array", "for"}, Items: []learnItem{
			{Use: "for (const x of list)", Keys: []string{"of"}, Why: "Loops over the values of arrays, strings, Maps and Sets.",
				Like: "Like taking each item out of a box, one at a time.", Example: "for (const user of users) {\n  console.log(user.name);\n}"},
			{Use: ".map() · .filter() · .find()", Keys: []string{"map", "filter", "find"}, Why: "map and filter make a new array. find returns the first match or undefined.",
				Like: "Like a sieve and a sorting belt: the original pile stays as it is.", Example: "const names = users.map((u) => u.name);\nconst active = users.filter((u) => u.active);\nconst me = users.find((u) => u.id === id);"},
			{Use: ".at(-1)", Keys: []string{"at"}, Why: "The item at a position. Negative numbers count from the end: -1 is the last item.",
				Like: "Like saying 'the last person in the queue' without counting everyone.", Example: "const last = items.at(-1);"},
			{Use: ".toSorted() · .toReversed()", Keys: []string{"tosorted", "toreversed", "sort", "reverse"}, Why: "Return a sorted or reversed copy. .sort() and .reverse() change the original array. ES2023; Baseline 2023.",
				Like: "Like sorting a photocopy of a list and keeping the original as it was.", Example: "const sorted = prices.toSorted((a, b) => a - b);\nconst newestFirst = posts.toReversed();"},
			{Use: ".includes(x)", Keys: []string{"includes", "indexof"}, Why: "Returns true or false. Clearer than indexOf(x) !== -1, and it finds NaN.",
				Like: "Like asking 'is this name on the guest list?'", Example: "const isAdmin = roles.includes(\"admin\");"},
			{Use: "Object.entries(obj)", Keys: []string{"entries"}, Why: "An array of [key, value] pairs. Loop with for (const [k, v] of Object.entries(obj)).",
				Like: "Like a list of labels with what is under each one.", Example: "for (const [key, value] of Object.entries(obj)) {\n  console.log(key, value);\n}"},
			{Use: "structuredClone(obj)", Keys: []string{"structuredclone"}, Why: "A deep copy. It keeps Dates, Maps and Sets. A function inside throws a DataCloneError.",
				Like: "Like a full copy of a folder, including every folder inside it.", Example: "const draft = structuredClone(settings);\ndraft.theme = \"dark\";"},
			{Use: "new Map() · new Set()", Why: "Map: lookups with keys of any type. Set: a group of unique values.",
				Like: "Like a coat check with numbered tickets, and a guest list with no repeated names.", Example: "const byId = new Map(users.map((u) => [u.id, u]));\nconst unique = [...new Set(ids)];"},
		}},
		{Title: "Async code", Keys: []string{"promise", "then"}, Items: []learnItem{
			{Use: "async / await", Keys: []string{"async", "await"}, Why: "Async code that reads from top to bottom. Catch errors with try/catch.",
				Like: "Like waiting at the counter until your order is ready, then going on.", Example: "const res = await fetch(`/api/users/${id}`);\nconst user = await res.json();"},
			{Use: "await Promise.all([…])", Keys: []string{"all"}, Why: "Waits for several promises that are already running. It rejects as soon as one of them rejects.",
				Like: "Like waiting by the oven for several dishes that are all cooking at once.", Example: "const [user, posts] = await Promise.all([\n  getUser(id), getPosts(id),\n]);"},
			{Use: "Promise.allSettled([…])", Keys: []string{"allsettled"}, Why: "Waits for every task, including the ones that fail, and reports each result.",
				Like: "Like waiting for every runner to finish or drop out before writing the results.", Example: "const results = await Promise.allSettled(jobs);\nconst bad = results.filter((r) => r.status === \"rejected\");"},
			{Use: "fetch(url)", Keys: []string{"fetch"}, Why: "Built into browsers and Node 18+. HTTP errors such as 404 do not throw: check res.ok.",
				Like: "Like a letter that comes back: you must open it to see if it says 'no'.", Example: "const res = await fetch(\"/api/items\");\nif (!res.ok) throw new Error(`HTTP ${res.status}`);\nconst items = await res.json();"},
			{Use: "AbortSignal.timeout(5000)", Keys: []string{"abortsignal", "signal"}, Why: "Pass it as { signal } to fetch. The request stops after that many milliseconds.",
				Like: "Like a kitchen timer that ends a phone call when it rings.", Example: "const res = await fetch(url, {\n  signal: AbortSignal.timeout(5000),\n});"},
			{Use: "top-level await", Why: "await can be used directly in an ES module, outside any function.",
				Like: "Like being allowed to wait in the main hall, not only in a side room.", Example: "import { readFile } from \"node:fs/promises\";\nconst text = await readFile(\"config.json\", \"utf8\");"},
		}},
		{Title: "Modules", Keys: []string{"import", "export", "from"}, Items: []learnItem{
			{Use: "import { x } from \"./x.js\"", Why: "ES modules. In browsers and Node, relative imports need the full file name, including .js.",
				Like: "Like a full street address instead of 'the house near the shop'.", Example: "import { formatDate } from \"./utils/date.js\";"},
			{Use: "export function x", Why: "A named export. The import uses the same name, so search and rename find it.",
				Like: "Like a product with a fixed name on the label in every shop.", Example: "export function formatDate(d) {\n  return d.toISOString().slice(0, 10);\n}"},
			{Use: "\"type\": \"module\"", Why: "In package.json. Node then treats .js files as ES modules.",
				Like: "Like a sign on the door that says which language is spoken inside.", Example: "{ \"name\": \"my-app\", \"type\": \"module\" }"},
			{Use: "await import(\"./x.js\")", Why: "A dynamic import. It loads the module only when this line runs.",
				Like: "Like fetching a tool from the shed only when the job needs it.", Example: "button.addEventListener(\"click\", async () => {\n  const { openEditor } = await import(\"./editor.js\");\n});"},
			{Use: "import fs from \"node:fs\"", Keys: []string{"node:"}, Why: "The node: prefix marks a module that is built into Node.",
				Like: "Like a 'made in house' label on a product.", Example: "import fs from \"node:fs\";\nconst text = fs.readFileSync(\"notes.txt\", \"utf8\");"},
		}},
		{Title: "Errors and classes", Keys: []string{"try", "catch", "class"}, Items: []learnItem{
			{Use: "throw new Error(\"…\")", Keys: []string{"throw", "error"}, Why: "Throw Error objects, not strings. All major engines add a stack trace to them (not yet in ECMA-262).",
				Like: "Like a fault report that includes where and when it happened.", Example: "if (!user) {\n  throw new Error(`User ${id} not found`);\n}"},
			{Use: "new Error(msg, { cause })", Keys: []string{"cause"}, Why: "Keeps the original error when you wrap it in a new one.",
				Like: "Like a doctor's note that also names the first test result.", Example: "try { await save(doc); } catch (err) {\n  throw new Error(\"Save failed\", { cause: err });\n}"},
			{Use: "class A { count = 0 }", Why: "A class field. It sets a starting value without a constructor.",
				Like: "Like a new notebook that comes with page numbers already printed.", Example: "class Cart {\n  items = [];\n}"},
			{Use: "#secret", Keys: []string{"#"}, Why: "A private field or method. Code outside the class cannot read or change it.",
				Like: "Like a locked drawer that only the owner has a key for.", Example: "class Account {\n  #balance = 0;\n}"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "var", Why: "Function-scoped and hoisted. Use const or let, which are block-scoped.",
				Like: "Like a note left on the kitchen table that every room can change.", Example: "// instead:\nconst max = 10;\nlet count = 0;"},
			{Use: "==", Why: "Converts types before comparing, with surprising results. Use ===.",
				Like: "Like accepting an ID card because the first name matches.", Example: "// instead:\nif (input.value === \"\") showError();"},
			{Use: "a || b for defaults", Keys: []string{"||"}, Why: "|| also replaces 0, \"\" and false. Use ?? to replace only null and undefined.",
				Like: "Like throwing away an empty cup because it looks like no cup.", Example: "// instead:\nconst limit = options.limit ?? 20;"},
			{Use: "for…in on arrays", Keys: []string{"in"}, Why: "Gives the keys as strings and can include inherited keys. Use for…of.",
				Like: "Like reading the seat numbers instead of the names of the guests.", Example: "// instead:\nfor (const item of items) render(item);"},
			{Use: "JSON.parse(JSON.stringify(x))", Why: "Dates become strings. undefined properties are dropped. Maps and Sets become {}. Use structuredClone.",
				Like: "Like faxing a photo to copy it: details are lost.", Example: "// instead:\nconst copy = structuredClone(state);"},
			{Use: "long .then() chains", Why: "async/await is easier to follow and works with try/catch.",
				Like: "Like a list of instructions written as one long sentence.", Example: "// instead:\nconst res = await fetch(url);\nconst data = await res.json();"},
			{Use: "eval() · new Function()", Keys: []string{"eval"}, Why: "Runs text as code. This is a security risk and blocks many optimisations.",
				Like: "Like following any note pushed under your door without checking who wrote it.", Example: "// instead:\nconst data = JSON.parse(text);"},
			{Use: "require() in new code", Keys: []string{"require"}, Why: "CommonJS is the older Node module system. Use import in new code.",
				Like: "Like writing new forms on an old template that is being phased out.", Example: "// instead:\nimport { readFile } from \"node:fs/promises\";"},
		}},
	},
}

var learnTypeScript = learnTopic{
	Name:   "TypeScript",
	Match:  []string{"typescript", "tsx", ".ts", ".tsx", ".mts", ".cts"},
	Source: "TypeScript Handbook (Everyday Types) · TSConfig Reference · release notes 4.9 and 5.8",
	Sections: []learnSection{
		{Title: "Setup (tsconfig.json)", Keys: []string{"tsconfig", "compileroptions"}, Items: []learnItem{
			{Use: "\"strict\": true", Keys: []string{"strict"}, Why: "Turns on the whole family of strict checks. Start every project with it.",
				Like: "Like turning on every safety check on a machine before you use it.", Example: "{\n  \"compilerOptions\": { \"strict\": true }\n}"},
			{Use: "\"noUncheckedIndexedAccess\"", Keys: []string{"nouncheckedindexedaccess"}, Why: "list[i] gets the type T | undefined, so you must check it before use.",
				Like: "Like a cloakroom that reminds you a ticket number may have no coat.", Example: "{\n  \"compilerOptions\": { \"noUncheckedIndexedAccess\": true }\n}"},
			{Use: "\"verbatimModuleSyntax\": true", Keys: []string{"verbatimmodulesyntax"}, Why: "Imports without type stay in the output. Imports marked type are dropped. TypeScript 5.0+.",
				Like: "Like a translator who must not drop or add any sentence.", Example: "{\n  \"compilerOptions\": { \"verbatimModuleSyntax\": true }\n}"},
			{Use: "\"module\": \"nodenext\"", Keys: []string{"nodenext"}, Why: "For code that Node runs. It follows Node's own module rules.",
				Like: "Like following the local traffic rules of the country you drive in.", Example: "{\n  \"compilerOptions\": { \"module\": \"nodenext\" }\n}"},
			{Use: "\"moduleResolution\": \"bundler\"", Keys: []string{"moduleresolution", "bundler"}, Why: "For code built by a bundler such as Vite or esbuild.",
				Like: "Like packing for a moving company that will sort the boxes for you.", Example: "{ \"compilerOptions\": {\n  \"module\": \"esnext\", \"moduleResolution\": \"bundler\"\n} }"},
			{Use: "tsc --noEmit", Keys: []string{"tsc", "noemit"}, Why: "Checks types without writing files. Use it when another tool builds the JavaScript.",
				Like: "Like a proofreader who marks mistakes but does not print the book.", Example: "npx tsc --noEmit"},
		}},
		{Title: "Types", Items: []learnItem{
			{Use: "unknown", Why: "For values you have not checked yet, such as parsed JSON. You must narrow it before use.",
				Like: "Like a parcel you must open and check before you use what is inside.", Example: "const data: unknown = JSON.parse(text);\nif (typeof data === \"string\") console.log(data);"},
			{Use: "string | null", Keys: []string{"|", "union"}, Why: "A union type: the value is one of the listed types.",
				Like: "Like a ticket that is valid for the bus or the train.", Example: "let selectedId: string | null = null;"},
			{Use: "\"small\" | \"large\"", Why: "A union of literal types: a fixed set of allowed values.",
				Like: "Like a coffee menu with only two sizes.", Example: "type Size = \"small\" | \"medium\" | \"large\";\nconst size: Size = \"medium\";"},
			{Use: "type", Why: "A type alias. Needed for unions, tuples and computed types. It also works for objects.",
				Like: "Like a nickname for a long description.", Example: "type ID = string | number;\ntype Point = [x: number, y: number];"},
			{Use: "interface", Why: "An object shape. The Handbook suggests it for objects until you need a feature of type.",
				Like: "Like a job description that other roles can build on.", Example: "interface User { id: string; name: string }\ninterface Admin extends User { role: string }"},
			{Use: "readonly · readonly T[]", Keys: []string{"readonly"}, Why: "Marks a property or array that must not be changed after creation.",
				Like: "Like a document under glass: you can read it but not write on it.", Example: "type Point = { readonly x: number; readonly y: number };\nconst ids: readonly string[] = [\"a\", \"b\"];"},
			{Use: "[string, number]", Keys: []string{"tuple"}, Why: "A tuple: an array with a fixed length and a type for each position.",
				Like: "Like a form with exactly two boxes: name, then age.", Example: "type Entry = [key: string, value: number];\nconst e: Entry = [\"apples\", 3];"},
		}},
		{Title: "Inference and checks", Items: []learnItem{
			{Use: "(id: string) => …", Why: "Annotate function parameters. TypeScript infers the types of most local variables.",
				Like: "Like labelling the inputs of a machine; the machine works out the rest.", Example: "const findUser = (id: string) =>\n  users.find((u) => u.id === id);"},
			{Use: "satisfies Config", Keys: []string{"satisfies"}, Why: "Checks that a value matches a type and keeps the value's own exact type. TypeScript 4.9+.",
				Like: "Like an inspector who checks a house against the rules but does not repaint it.", Example: "const config = {\n  port: 3000, host: \"localhost\",\n} satisfies Config;"},
			{Use: "as const", Why: "Gives a value its exact literal types and makes it read-only.",
				Like: "Like carving a sign in stone instead of writing it in chalk.", Example: "const ROLES = [\"admin\", \"user\"] as const;\ntype Role = (typeof ROLES)[number];"},
		}},
		{Title: "Narrowing", Keys: []string{"if", "switch"}, Items: []learnItem{
			{Use: "typeof x === \"string\"", Keys: []string{"typeof"}, Why: "Inside this if, TypeScript knows x is a string.",
				Like: "Like checking a key's shape before trying it in the lock.", Example: "if (typeof value === \"string\") {\n  return value.trim();\n}"},
			{Use: "\"key\" in obj", Keys: []string{"in"}, Why: "Narrows by whether the object has that property.",
				Like: "Like checking whether a bag has a side pocket.", Example: "if (\"email\" in contact) {\n  sendEmail(contact.email);\n}"},
			{Use: "x instanceof Date", Keys: []string{"instanceof"}, Why: "Narrows to the type of a class.",
				Like: "Like checking a car's make on its badge.", Example: "if (err instanceof Error) {\n  console.error(err.message);\n}"},
			{Use: "kind: \"circle\"", Keys: []string{"kind"}, Why: "A discriminated union: each type has the same tag field. switch (s.kind) narrows each case.",
				Like: "Like coloured tags on luggage that tell the handler how to treat each bag.", Example: "type Shape =\n  | { kind: \"circle\"; r: number }\n  | { kind: \"square\"; size: number };"},
			{Use: "(x: unknown): x is User", Keys: []string{"is"}, Why: "A type predicate. When the function returns true, x is a User after the call.",
				Like: "Like a door guard whose 'yes' means the visitor is a member.", Example: "function isUser(x: unknown): x is User {\n  return typeof x === \"object\" && x !== null && \"id\" in x;\n}"},
			{Use: "const _: never = x", Keys: []string{"never"}, Why: "In the default case of a switch: an error appears if a union case is not handled.",
				Like: "Like a checklist that will not close while a box is still empty.", Example: "default:\n  const _: never = shape;\n  throw new Error(\"Unknown shape\");"},
		}},
		{Title: "Instead of enums", Keys: []string{"enum"}, Items: []learnItem{
			{Use: "type Dir = \"up\" | \"down\"", Why: "A union of strings. It adds no JavaScript to the output.",
				Like: "Like a list of allowed answers printed on the form.", Example: "type Status = \"idle\" | \"loading\" | \"error\";\nlet status: Status = \"idle\";"},
			{Use: "const Dir = { … } as const", Why: "Use this when you also need the values at runtime.",
				Like: "Like a printed price list you can also read out loud.", Example: "const Dir = { Up: \"up\", Down: \"down\" } as const;\nmove(Dir.Up);"},
			{Use: "(typeof Dir)[keyof typeof Dir]", Keys: []string{"keyof"}, Why: "The union of that object's values, such as \"up\" | \"down\".",
				Like: "Like reading all the prices off the price list.", Example: "type Dir = (typeof Dir)[keyof typeof Dir];"},
			{Use: "keyof typeof obj", Why: "The union of an object's keys.",
				Like: "Like reading all the item names off the price list.", Example: "const labels = { en: \"English\", fr: \"French\" };\ntype Lang = keyof typeof labels;"},
		}},
		{Title: "Generics and utility types", Keys: []string{"generic"}, Items: []learnItem{
			{Use: "<T>", Why: "A type parameter. function first<T>(list: T[]): T | undefined keeps the item type.",
				Like: "Like a box labelled 'same as what you put in'.", Example: "function first<T>(list: T[]): T | undefined {\n  return list[0];\n}"},
			{Use: "<T extends { id: string }>", Keys: []string{"extends"}, Why: "Limits T to types that have at least these fields.",
				Like: "Like a parking space for any car shorter than five metres.", Example: "function byId<T extends { id: string }>(items: T[]) {\n  return new Map(items.map((x) => [x.id, x]));\n}"},
			{Use: "Partial<T> · Required<T>", Keys: []string{"partial", "required"}, Why: "All fields optional, or all fields required.",
				Like: "Like a draft form and a final form of the same paper.", Example: "type UserPatch = Partial<User>;\ntype FullConfig = Required<Config>;"},
			{Use: "Pick<T, \"a\"> · Omit<T, \"b\">", Keys: []string{"pick", "omit"}, Why: "Keeps only the named fields, or removes the named fields.",
				Like: "Like photocopying only some pages of a document.", Example: "type UserPreview = Pick<User, \"id\" | \"name\">;\ntype NewUser = Omit<User, \"id\">;"},
			{Use: "Record<K, V>", Keys: []string{"record"}, Why: "An object type with keys of type K and values of type V.",
				Like: "Like a phone book: every name has one number.", Example: "const counts: Record<string, number> = {};\ntype Prices = Record<\"small\" | \"large\", number>;"},
			{Use: "ReturnType<typeof f>", Keys: []string{"returntype"}, Why: "The type that a function returns.",
				Like: "Like reading the 'output' line on a machine's label.", Example: "type Store = ReturnType<typeof createStore>;"},
			{Use: "Awaited<T>", Keys: []string{"awaited"}, Why: "The type a Promise gives when it is awaited.",
				Like: "Like the meal you get when the order ticket is called.", Example: "type User = Awaited<ReturnType<typeof fetchUser>>;"},
		}},
		{Title: "Imports", Keys: []string{"import", "export"}, Items: []learnItem{
			{Use: "import type { User }", Why: "A type-only import. It is removed from the JavaScript output.",
				Like: "Like a blueprint you use while building and do not ship with the house.", Example: "import type { User } from \"./types.js\";"},
			{Use: "import { type User, load }", Why: "Types and values in one import. Only load stays in the output.",
				Like: "Like one delivery with both tools and their manuals.", Example: "import { type User, loadUser } from \"./users.js\";"},
			{Use: "export type { User }", Why: "Re-exports only the type.",
				Like: "Like passing on a blueprint without the building.", Example: "export type { User } from \"./types.js\";"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "any", Why: "Turns off type checking for that value. Use unknown and narrow it.",
				Like: "Like a security gate that waves everyone through.", Example: "// instead:\nconst data: unknown = await res.json();"},
			{Use: "enum", Why: "It generates extra JavaScript. The option erasableSyntaxOnly (TypeScript 5.8+) reports it. Use a union.",
				Like: "Like a list that needs its own filing cabinet when a sheet of paper would do.", Example: "// instead:\ntype Color = \"red\" | \"green\" | \"blue\";"},
			{Use: "namespace", Why: "An older way to group code. Use ES modules.",
				Like: "Like a filing system the office no longer uses.", Example: "// instead:\nimport * as utils from \"./utils.js\";"},
			{Use: "x as User", Keys: []string{"as"}, Why: "A type assertion skips the check. Use satisfies, or narrow with a real check.",
				Like: "Like writing 'checked' on a form without looking at it.", Example: "// instead:\nconst config = { port: 3000 } satisfies Config;"},
			{Use: "x!", Keys: []string{"!"}, Why: "A non-null assertion hides possible null bugs. Check for null instead.",
				Like: "Like saying 'the bridge is fine' without looking at it.", Example: "// instead:\nconst el = document.querySelector(\"#app\");\nif (!el) throw new Error(\"#app not found\");"},
			{Use: "// @ts-ignore", Keys: []string{"@ts-ignore", "@ts-expect-error"}, Why: "Use // @ts-expect-error. It reports when the error below it is gone.",
				Like: "Like a reminder note that removes itself when the job is done.", Example: "// instead:\n// @ts-expect-error testing a bad argument\nformatDate(\"not a date\");"},
			{Use: "String · Number · Object", Why: "Wrapper object types. Use string, number and a real object shape.",
				Like: "Like writing 'a thing' on a label instead of what the thing is.", Example: "// instead:\nlet name: string = \"Ana\";\nlet user: { id: number; name: string };"},
			{Use: "Function · {}", Why: "Calling a Function returns any. {} allows any value except null and undefined. Write the real shape.",
				Like: "Like a delivery note that says 'some stuff'.", Example: "// instead:\ntype Handler = (e: MouseEvent) => void;\ntype Data = Record<string, unknown>;"},
		}},
	},
}

var learnJSON = learnTopic{
	Name:   "JSON / YAML / TOML",
	Match:  []string{"json", "yaml", "toml", ".json", ".jsonc", ".yaml", ".yml", ".toml"},
	Source: "RFC 8259 (JSON) · YAML 1.2.2 · yaml.org FAQ · TOML 1.0.0",
	Sections: []learnSection{
		{Title: "JSON rules", Items: []learnItem{
			{Use: "\"key\": \"value\"", Keys: []string{"\""}, Why: "Keys and strings use double quotes. Single quotes are not valid JSON.",
				Like: "Like a form that only accepts black ink.", Example: "{ \"name\": \"my-app\", \"version\": \"1.0.0\" }"},
			{Use: "[1, 2, 3]", Keys: []string{","}, Why: "No comma after the last item. [1, 2,] is an error.",
				Like: "Like a list read aloud: you do not say 'and' after the last item.", Example: "{ \"tags\": [\"web\", \"api\", \"cli\"] }"},
			{Use: "true · false · null", Why: "Lower case only. JSON has no undefined, NaN or Infinity.",
				Like: "Like a form with only three tick boxes: yes, no and empty.", Example: "{ \"active\": true, \"deletedAt\": null }"},
			{Use: "no comments", Keys: []string{"//"}, Why: "JSON has no comments. Some tools, such as tsconfig.json, accept them; plain JSON parsers do not.",
				Like: "Like a machine-read form: notes in the margin make it fail.", Example: "{ \"description\": \"Build settings for the web app\" }"},
			{Use: "\"id\": \"9007199254740993\"", Why: "Write very large numbers as strings. RFC 8259 calls integers interoperable only up to 2^53 − 1.",
				Like: "Like writing a long account number as text so no digit gets rounded.", Example: "{ \"orderId\": \"9007199254740993\" }"},
			{Use: "UTF-8", Why: "JSON sent outside a closed system must be UTF-8. Senders must not add a byte order mark.",
				Like: "Like agreeing on one alphabet for every letter you send.", Example: "Content-Type: application/json"},
		}},
		{Title: "JSON in code", Items: []learnItem{
			{Use: "JSON.parse(text)", Keys: []string{"parse"}, Why: "Turns JSON text into a value. Wrap it in try/catch: bad input throws.",
				Like: "Like unpacking a parcel and checking it is not damaged.", Example: "let config = {};\ntry { config = JSON.parse(text); }\ncatch { console.warn(\"Bad config file\"); }"},
			{Use: "JSON.stringify(x, null, 2)", Keys: []string{"stringify"}, Why: "Turns a value into JSON text. The 2 indents it with 2 spaces.",
				Like: "Like packing a parcel neatly so the contents are easy to see.", Example: "await writeFile(\"data.json\", JSON.stringify(data, null, 2));"},
			{Use: "res.json()", Why: "With fetch: reads the response body and parses it as JSON.",
				Like: "Like a mailroom that opens and sorts a parcel for you.", Example: "const res = await fetch(\"/api/users\");\nconst users = await res.json();"},
		}},
		{Title: "YAML basics", Keys: []string{":"}, Items: []learnItem{
			{Use: "key: value", Why: "A space after the colon is required.",
				Like: "Like a label and its value on a name badge.", Example: "name: my-app\nport: 8080\ndebug: false"},
			{Use: "2 spaces", Keys: []string{"indent"}, Why: "Indentation shows nesting. Tabs are not allowed. 2 spaces is the common size.",
				Like: "Like an outline where each sub-point is indented under its point.", Example: "server:\n  host: localhost\n  port: 8080"},
			{Use: "- item", Keys: []string{"-"}, Why: "A list item: a dash, then a space.",
				Like: "Like a bullet on a shopping list.", Example: "steps:\n  - uses: actions/checkout@v4\n  - run: npm test"},
			{Use: "# comment", Keys: []string{"#"}, Why: "A comment runs from # to the end of the line. Put a space before the # unless it starts the line.",
				Like: "Like a pencil note in the margin.", Example: "# Port for local development\nport: 8080  # default is 80"},
			{Use: "run: |", Keys: []string{"|"}, Why: "A literal block: the text below keeps its line breaks. Good for scripts.",
				Like: "Like a poem copied line by line.", Example: "run: |\n  npm ci\n  npm test"},
			{Use: "text: >", Keys: []string{">"}, Why: "A folded block: single line breaks become spaces.",
				Like: "Like a paragraph that wraps to fit the page.", Example: "description: >\n  A small tool that resizes\n  images from the command line."},
			{Use: "---", Why: "Starts a new document in the same file.",
				Like: "Like a divider between letters in one envelope.", Example: "kind: Service\n---\nkind: Deployment"},
			{Use: "&base · *base", Keys: []string{"&", "*"}, Why: "An anchor (&) names a node. An alias (*) reuses it later in the same document.",
				Like: "Like 'see above' in a document, pointing to a named part.", Example: "x-env: &env\n  NODE_ENV: production\napi: { environment: *env }"},
		}},
		{Title: "YAML quoting", Items: []learnItem{
			{Use: "\"no\" · \"yes\" · \"on\" · \"off\"", Why: "Quote these. YAML 1.1 parsers read them as true or false. YAML 1.2 reads them as text.",
				Like: "Like writing the country code 'NO' in quotes so nobody reads it as the word 'no'.", Example: "country: \"NO\"\nconfirm: \"yes\""},
			{Use: "\"1.10\"", Why: "Quote version numbers. Unquoted, 1.10 is the number 1.1.",
				Like: "Like writing a phone number as text so the leading zero is kept.", Example: "python-version: \"3.10\""},
			{Use: "\"12:30\"", Why: "Quote times. YAML 1.1 parsers read 12:30 as the number 750 (base 60).",
				Like: "Like writing 'half past twelve' so nobody does arithmetic with it.", Example: "ports:\n  - \"8080:80\""},
			{Use: "\"null\" · \"~\"", Keys: []string{"null", "~"}, Why: "Unquoted, null and ~ mean no value. Quote them when you mean the text.",
				Like: "Like writing the word 'empty' on a box that is not empty.", Example: "path: \"~\"\nlabel: \"null\""},
			{Use: "\"a: b\" · \"see #4\"", Why: "Quote text that contains \": \" or \" #\". Unquoted, they change the meaning of the line.",
				Like: "Like putting a sentence with a colon in quotes so it is not read as a label.", Example: "title: \"Note: read this first\"\nissue: \"see #4\""},
			{Use: "'C:\\path'", Keys: []string{"'"}, Why: "Single quotes: no escapes; write '' for one quote. Double quotes allow escapes such as \\n.",
				Like: "Like the difference between a photocopy and a typed copy with corrections.", Example: "path: 'C:\\Users\\ana'\nmsg: \"Line one\\nLine two\""},
		}},
		{Title: "TOML", Keys: []string{"="}, Items: []learnItem{
			{Use: "key = \"value\"", Why: "Strings always need quotes. Every value has a clear type.",
				Like: "Like a form where every box says what kind of answer goes in it.", Example: "name = \"my-app\"\nport = 8080\ndebug = false"},
			{Use: "[server]", Keys: []string{"["}, Why: "A table header. The keys below it belong to it until the next header.",
				Like: "Like a heading in a filing cabinet drawer.", Example: "[server]\nhost = \"0.0.0.0\"\nport = 8080"},
			{Use: "[server.tls]", Why: "A table inside the server table.",
				Like: "Like a folder inside a drawer.", Example: "[server.tls]\ncert = \"cert.pem\"\nkey = \"key.pem\""},
			{Use: "[[plugin]]", Keys: []string{"[["}, Why: "An array of tables. Each [[plugin]] header adds one entry to the list.",
				Like: "Like adding another card to a card index.", Example: "[[bin]]\nname = \"cli\"\npath = \"src/main.rs\""},
			{Use: "a.b = 1", Why: "A dotted key: sets one value inside a nested table.",
				Like: "Like writing 'drawer 2, folder A' as one address.", Example: "[tool.ruff]\nlint.select = [\"E\", \"F\"]"},
			{Use: "'C:\\path'", Why: "A literal string: backslashes stay exactly as typed.",
				Like: "Like a photocopy: nothing is changed.", Example: "path = 'C:\\Users\\ana\\data'\npattern = '\\d+\\.\\d+'"},
			{Use: "\"\"\"…\"\"\"", Keys: []string{"\"\"\""}, Why: "A multi-line string.",
				Like: "Like a text box that allows several lines.", Example: "description = \"\"\"\nA small tool\nthat resizes images.\"\"\""},
			{Use: "1979-05-27T07:32:00Z", Why: "Dates and times are their own type. They need no quotes.",
				Like: "Like a calendar entry, not a note that mentions a date.", Example: "released = 1979-05-27T07:32:00Z\nbirthday = 1979-05-27"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "comments in .json", Why: "Plain JSON parsers reject them. Use .jsonc only where the tool supports it.",
				Like: "Like writing on a barcode: the scanner can no longer read it.", Example: "// instead: (.jsonc)\n{ \"port\": 8080 } // local dev only"},
			{Use: "trailing commas in JSON", Why: "JSON parsers reject a comma after the last item.",
				Like: "Like a sentence that ends with 'and'.", Example: "// instead:\n{ \"tags\": [\"web\", \"api\"] }"},
			{Use: "tabs in YAML", Keys: []string{"tab"}, Why: "YAML does not allow tabs for indentation. The file will not load.",
				Like: "Like a ruler with no markings: the parser cannot measure the indent.", Example: "# instead:\nserver:\n  port: 8080"},
			{Use: "duplicate keys", Why: "YAML and TOML forbid them. JSON parsers handle them in different ways.",
				Like: "Like two different answers in the same box on a form.", Example: "# instead:\nports: [80, 443]"},
			{Use: "secrets in config files", Keys: []string{"password", "token", "secret"}, Why: "Do not commit passwords or keys. Use environment variables or a secret store.",
				Like: "Like taping your house key to the front door.", Example: "# instead:\nenvironment:\n  DB_PASSWORD: ${DB_PASSWORD}"},
			{Use: "mixing .yml and .yaml", Keys: []string{"yml"}, Why: "Use one file ending per project. yaml.org asks for .yaml.",
				Like: "Like spelling a street name two ways on the same map.", Example: "# instead:\ngit mv config.yml config.yaml"},
		}},
	},
}
